    // ---------------------------------------------------------------------------
    // discover_entries: always-visible (force-include) patterns
    // ---------------------------------------------------------------------------

    /// Build a temp project layout:
    ///
    /// ```text
    /// .gitignore            (content passed by the test)
    /// docs/plans/design.md
    /// docs/plans/notes/inner.md
    /// src/main.rs
    /// target/build.txt
    /// ```
    fn fixture_project(gitignore: &str) -> (TempDir, std::path::PathBuf) {
        let dir = TempDir::new().unwrap();
        let root = dir.path().to_path_buf();

        fs::write(root.join(".gitignore"), gitignore).unwrap();
        fs::create_dir_all(root.join("docs/plans/notes")).unwrap();
        fs::write(root.join("docs/plans/design.md"), "plan").unwrap();
        fs::write(root.join("docs/plans/notes/inner.md"), "notes").unwrap();
        fs::create_dir_all(root.join("src")).unwrap();
        fs::write(root.join("src/main.rs"), "fn main() {}").unwrap();
        fs::create_dir_all(root.join("target")).unwrap();
        fs::write(root.join("target/build.txt"), "artifact").unwrap();

        (dir, root)
    }

    fn paths_of(entries: &[FileMatch]) -> Vec<&str> {
        entries.iter().map(|e| e.path.as_str()).collect()
    }

    #[test]
    fn discover_entries_hides_gitignored_dir_and_children() {
        let (_dir, root) = fixture_project("docs/plans/\n");
        let entries = FileDiscovery::discover_entries(&root, &[]);
        let paths = paths_of(&entries);
        assert!(!paths.contains(&"docs/plans"), "gitignored dir must be hidden");
        assert!(!paths.contains(&"docs/plans/design.md"), "child of gitignored dir must be hidden");
        assert!(!paths.contains(&"docs/plans/notes"), "nested child dir must be hidden");
        assert!(!paths.contains(&"docs/plans/notes/inner.md"), "nested child file must be hidden");
    }

    #[test]
    fn discover_entries_force_includes_listed_gitignored_dir() {
        let (_dir, root) = fixture_project("docs/plans/\n");
        let patterns = vec!["docs/plans/".to_string()];
        let entries = FileDiscovery::discover_entries(&root, &patterns);
        let paths = paths_of(&entries);
        assert!(paths.contains(&"docs/plans"), "force-included dir must be visible");
        assert!(paths.contains(&"docs/plans/design.md"), "child file must be visible");
        assert!(paths.contains(&"docs/plans/notes"), "nested child dir must be visible");
        assert!(paths.contains(&"docs/plans/notes/inner.md"), "nested child file must be visible");
    }

    #[test]
    fn discover_entries_empty_always_visible_restores_baseline() {
        let (_dir, root) = fixture_project("docs/plans/\ndocs/reviews/\n");
        let entries = FileDiscovery::discover_entries(&root, &[]);
        let paths = paths_of(&entries);
        // Empty list opts out: every gitignored path stays hidden
        assert!(!paths.contains(&"docs/plans"));
        assert!(!paths.contains(&"docs/plans/design.md"));
    }

    #[test]
    fn discover_entries_non_gitignored_path_unaffected_by_list() {
        let (_dir, root) = fixture_project("docs/plans/\n");
        for patterns in [&[] as &[String], &["docs/plans/".to_string()], &["nonexistent/".to_string()]] {
            let entries = FileDiscovery::discover_entries(&root, patterns);
            let paths = paths_of(&entries);
            assert!(paths.contains(&"src"), "non-gitignored dir must stay visible");
            assert!(paths.contains(&"src/main.rs"), "non-gitignored file must stay visible");
        }
    }

    #[test]
    fn discover_entries_noise_dir_stays_excluded_even_if_listed() {
        let (_dir, root) = fixture_project("target/\n");
        let patterns = vec!["target/".to_string()];
        let entries = FileDiscovery::discover_entries(&root, &patterns);
        let paths = paths_of(&entries);
        assert!(!paths.contains(&"target"), "hard noise-dir exclusion cannot be force-included");
        assert!(!paths.contains(&"target/build.txt"), "child of noise dir must stay hidden");
    }
